using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post to retrieve (1-100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}", cancellationToken);
        return JsonSerializer.Serialize(post, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts to this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        logger.LogInformation("Listing posts from {Url}", url);
        var posts = await client.GetFromJsonAsync<JsonElement>(url, cancellationToken);
        return JsonSerializer.Serialize(posts, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(ReadOnly = false), Description("Create a new post with a title and body.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the new post")] string body,
        [Description("User ID of the author")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = httpFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync("/posts",
            new { title, body, userId }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return result;
    }
}

